import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_fp16.h>
#include <math.h>

#define WARP_SIZE 32
#define ROWS_PER_BLOCK 32
#define THREADS (ROWS_PER_BLOCK*WARP_SIZE)
__inline__ __device__ float warpReduceSum(float val){
    for(int offset=16; offset>0; offset>>=1)
        val += __shfl_down_sync(0xffffffff, val, offset);
    return val;
}
__device__ __forceinline__ void load_kv_tile(const half* __restrict__ K_ptr,
                                              const half* __restrict__ V_ptr,
                                              float* __restrict__ k_dst,
                                              float* __restrict__ v_dst,
                                              int D, int tid, int nthreads){
    int half_threads = nthreads >> 1;
    int D2 = D >> 1;
    if(tid < half_threads){
        for(int idx = tid; idx < D2; idx += half_threads){
            int off = idx*2;
            half2 kv = *reinterpret_cast<const half2*>(K_ptr + off);
            float2 kf = __half22float2(kv);
            k_dst[off+0]=kf.x; k_dst[off+1]=kf.y;
        }
    } else {
        int t2 = tid - half_threads;
        for(int idx = t2; idx < D2; idx += half_threads){
            int off = idx*2;
            half2 vv = *reinterpret_cast<const half2*>(V_ptr + off);
            float2 vf = __half22float2(vv);
            v_dst[off+0]=vf.x; v_dst[off+1]=vf.y;
        }
    }
}
__global__ void flash_attn_kernel(const half* __restrict__ Q,
                                    const half* __restrict__ K,
                                    const half* __restrict__ V,
                                    half* __restrict__ O,
                                    int B, int H, int S, int D){
    int num_tiles = (S + ROWS_PER_BLOCK - 1) / ROWS_PER_BLOCK;
    int tileIdx = blockIdx.x;
    int bh = tileIdx / num_tiles;
    int tile = tileIdx % num_tiles;
    int b = bh / H;
    int h = bh % H;
    int row_start = tile * ROWS_PER_BLOCK;
    int rows_in_tile = min(ROWS_PER_BLOCK, S - row_start);
    int tid = threadIdx.x;
    int nthreads = blockDim.x;
    int lane = tid & (WARP_SIZE-1);
    int wid = tid >> 5;
    extern __shared__ float smem[];
    float* k_buf[2];
    float* v_buf[2];
    k_buf[0] = smem;
    k_buf[1] = smem + D;
    v_buf[0] = smem + 2*D;
    v_buf[1] = smem + 3*D;
    size_t base_idx = ((size_t)(b*H+h)*S);
    const half* K_base = K + base_idx*D;
    const half* V_base = V + base_idx*D;
    int per_thread = D / WARP_SIZE;
    int base_d = lane * per_thread;
    int row = wid;
    bool active = (row < rows_in_tile);
    // Each warp owns exactly one query row; stage that row's Q values
    // directly into registers instead of shared memory.
    float q_reg[64];
    #pragma unroll
    for(int k=0;k<64;k++) q_reg[k] = 0.0f;
    if(active){
        const half* Q_ptr = Q + (base_idx + row_start + row)*D + base_d;
        int per_thread4_q = per_thread >> 2;
        #pragma unroll
        for(int k=0;k<per_thread4_q;k++){
            int off = k*4;
            const float2* Qvec = reinterpret_cast<const float2*>(Q_ptr + off);
            float2 qv2 = *Qvec;
            half2 q0 = *reinterpret_cast<half2*>(&qv2.x);
            half2 q1 = *reinterpret_cast<half2*>(&qv2.y);
            float2 qf0 = __half22float2(q0);
            float2 qf1 = __half22float2(q1);
            q_reg[off+0]=qf0.x; q_reg[off+1]=qf0.y;
            q_reg[off+2]=qf1.x; q_reg[off+3]=qf1.y;
        }
    }
    float acc[64];
    #pragma unroll
    for(int k=0;k<64;k++) acc[k] = 0.0f;
    float scale = rsqrtf((float)D);
    float m = -1e30f;
    float l = 0.0f;
    // Double-buffered pipelined load of K/V tiles: prefetch the next
    // row's K/V into the alternate shared-memory buffer while the
    // current row is being consumed, cutting synchronization points
    // from two __syncthreads() per iteration down to one.
    if(S > 0){
        load_kv_tile(K_base, V_base, k_buf[0], v_buf[0], D, tid, nthreads);
    }
    __syncthreads();
    for(int j=0;j<S;j++){
        int cur = j & 1;
        int nxt = 1 - cur;
        if(j+1 < S){
            const half* K_ptr_next = K_base + (size_t)(j+1)*D;
            const half* V_ptr_next = V_base + (size_t)(j+1)*D;
            load_kv_tile(K_ptr_next, V_ptr_next, k_buf[nxt], v_buf[nxt], D, tid, nthreads);
        }
        if(active){
            const float4* q_row4 = reinterpret_cast<const float4*>(q_reg);
            const float4* k_smem4 = reinterpret_cast<const float4*>(k_buf[cur] + base_d);
            int per_thread4 = per_thread >> 2;
            float partial = 0.0f;
            #pragma unroll
            for(int k=0;k<per_thread4;k++){
                float4 qv = q_row4[k];
                float4 kv = k_smem4[k];
                partial += qv.x*kv.x + qv.y*kv.y + qv.z*kv.z + qv.w*kv.w;
            }
            partial = warpReduceSum(partial);
            float factor = 0.0f, expscore = 0.0f;
            if(lane==0){
                float score = partial*scale;
                float m_old = m;
                float newmax = fmaxf(m_old, score);
                factor = expf(m_old - newmax);
                expscore = expf(score - newmax);
                l = l*factor + expscore;
                m = newmax;
            }
            factor = __shfl_sync(0xffffffff, factor, 0);
            expscore = __shfl_sync(0xffffffff, expscore, 0);
            const float4* v_smem4 = reinterpret_cast<const float4*>(v_buf[cur] + base_d);
            float4* acc4 = reinterpret_cast<float4*>(acc);
            #pragma unroll
            for(int k=0;k<per_thread4;k++){
                float4 vv = v_smem4[k];
                float4 av = acc4[k];
                av.x = av.x*factor + expscore*vv.x;
                av.y = av.y*factor + expscore*vv.y;
                av.z = av.z*factor + expscore*vv.z;
                av.w = av.w*factor + expscore*vv.w;
                acc4[k] = av;
            }
        }
        __syncthreads();
    }
    if(active){
        float l_final = __shfl_sync(0xffffffff, l, 0);
        half* O_ptr = O + (base_idx + row_start + row)*D;
        float inv_l = 1.0f / l_final;
        #pragma unroll
        for(int k=0;k<per_thread;k+=2){
            int d = base_d+k;
            half2 h2 = __floats2half2_rn(acc[k]*inv_l, acc[k+1]*inv_l);
            *reinterpret_cast<half2*>(O_ptr+d) = h2;
        }
    }
}
torch::Tensor flash_attention_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V){
    TORCH_CHECK(Q.is_cuda() && K.is_cuda() && V.is_cuda(), "inputs must be CUDA tensors");
    TORCH_CHECK(Q.scalar_type() == torch::kHalf, "expected half precision");
    Q = Q.contiguous();
    K = K.contiguous();
    V = V.contiguous();
    auto B = Q.size(0);
    auto H = Q.size(1);
    auto S = Q.size(2);
    auto D = Q.size(3);
    auto O = torch::empty_like(Q);
    int threads = THREADS;
    int num_tiles = (S + ROWS_PER_BLOCK - 1) / ROWS_PER_BLOCK;
    int blocks = B*H*num_tiles;
    size_t shmem = (size_t)4*D*sizeof(float);
    cudaFuncSetAttribute(flash_attn_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)shmem);
    flash_attn_kernel<<<blocks, threads, shmem>>>(
        reinterpret_cast<half*>(Q.data_ptr<at::Half>()),
        reinterpret_cast<half*>(K.data_ptr<at::Half>()),
        reinterpret_cast<half*>(V.data_ptr<at::Half>()),
        reinterpret_cast<half*>(O.data_ptr<at::Half>()),
        B, H, S, D
    );
    return O;
}
